  Theorem free_exit : forall (two : bool) s msF mo regs mem p (A cap : Z) (status : word) (pending : list byte) junk,
    as_VIS H s msF = mkst regs (Z_to_bv 64 0xa2ec4) mem rom -> as_AKREL H s (mkCfg msF mo) ->
    getr regs 2 = Z_to_bv 64 (bv_unsigned sp0 - 128) -> getr regs 4 = Z_to_bv 64 ATP -> getr regs 8 = status -> getr regs 9 = Z_to_bv 64 A ->
    bv_unsigned status < 256 ->
    as_RHEAP H s [(p, A, cap)] mem -> rw_cells asegs mem A [CB (Z.to_nat cap) junk] -> addressable mem A cap ->
    as_Cf H cap <= as_AL H s ->
    xstat two mem -> ostate pending mem -> (pending <> [] -> two = true) ->     (* [comment removed for export] *)
    fd_lookup (m_fds mo) (Z_to_bv 64 1) = Some (FdChannel (Z_to_bv 64 1)) ->
    m_channel_reader mo = true ->
    realizes asegs (mkCfg msF mo) (t_emit (W 1 pending) (t_exit (bv_and status (Z_to_bv 64 255)) (m_fs mo))).
  Proof using HCEIL H HH DL sp0 Hvsp HCE TRC rom SPlo SPhi SP16 lo Elo.
    (* [as_exit_flush] (As/AsExit.v:460) takes the channel reader right after its fd_lookup
       premise (:473), and the recorded proof here was one argument short of it, so this
       statement carries [m_channel_reader mo = true] after its own fd_lookup premise and the
       proof is written out as text on the shape of [free_exit] in openssl/echconfiglist_parser
       As/AsMainExit.v and spirv-tools/spvtools_binary_parser_fuzzer bpA/Drv/AsMainExit.v.  Each
       lemma is one the recorded proof named, and every constant is this unit's own: the free
       stub entry and return address from [aseg_I] (As/AsMainSegs.v:405-407), the thread pointer
       from [aseg_X] (:427), the return-address trace from [adrv_traces] (As/AsDrvDefs.v:152),
       the stdout cells from [astdout0]/[astdout_after] (As/AsDrvDefs.v:115-134) as [axH_of]
       (this file, :156-157), [as_exit_clean] (As/AsExit.v:504-505) and [as_exit_flush] (:462-465) read them.
       The reader at the exit model is [RDR], carried across the two [same_but_materialized]
       steps by [same_but_materialized_reader] (As/LazyRestrict.v:852) and across free's
       [as_MPRES] by [adl_rdr] (As/AsDriverLaws.v:44).  [Proof using] keeps the discharged
       statement's section arguments those of the recorded proof. *)
    intros two s msF mo regs mem p A cap status pending junk HV HA R2 R4 R8 R9 Hst RH HCB AD HCF XS OS Htwo Hfd1 RDR.
    pose proof (u64_range status) as HstR.
    pose proof SPlo as Hlo. pose proof SPhi as Hhi. pose proof SP16. pose proof Elo. pose proof aceil_loX as HCL. acb.
    pose proof (ah_blocks H HH _ _ _ (p, A, cap) RH ltac:(left; reflexivity)) as BR.
    pose proof BR as (B1 & B2 & B3 & B4 & B5 & B6 & B7). cbn [blk_addr blk_size fst snd] in *.
    assert (STK0 : stk_ok RSEGS mem (Z_to_bv 64 (bv_unsigned sp0 - 128)) MSTK).
    { eapply astk_stk_ok; [exact (xs_stk _ _ XS) | unfold MSTK; rewrite u_small by lia; lia | rewrite u_small by lia; lia | unfold MSTK; lia | lia]. }
    eapply (aseg_I H DL sp0 Hvsp s msF mo regs mem (getr regs 18) A status _ R2 R4 R8 R9 STK0 (amem_inv_ro_none _ (xs_inv _ _ XS)) (xs_relro _ _ XS));
      [| exact HV | exact HA].
    intros regs1 mem1 msF1 mo1 HV1 HA1 SB1 Q2 Q4 Q8 Q1 Q9 Q10 KP FM1 STK1.
    pose proof (xstat_frameL _ _ _ XS FM1) as XS1. pose proof (ostate_frameL _ _ _ OS FM1) as OS1.
    pose proof (rheap_frameL H HH sp0 Hvsp HCE _ _ _ _ RH FM1) as RH1.
    destruct (blkR_frameL H sp0 Hvsp HCE A cap mem mem1 junk 0%nat [] BR FM1 HCB AD ltac:(reflexivity) ltac:(lia)) as (CB1 & AD1 & _).
    destruct (aerrno_rw_any mem1) as [errv ERR]. destruct (xs_aux _ _ XS1) as [B' [AUX1 HB']].
    assert (STKlo : stk asegs mem1 lo (bv_unsigned sp0 - 128)).
    { destruct (xs_stk _ _ XS1) as (S1 & S2 & S3). split; [exact S1|]. split; [lia|]. intros a Ha. apply S3. lia. }
    change (Z_to_bv 64 0x73274) with (Z_to_bv 64 AFREE_STUB) in HV1.
    eapply (afree_call H HH DL regs1 mem1 msF1 mo1 s [(p, A, cap)] p A cap lo B' errv 0xa2ecc [] junk (shadow_of cap) _ HV1 HA1 Q1);
      [ lia | reflexivity | exact Q4 | exact Q10 | exact RH1 | left; reflexivity | exact HCF
      | exact CB1 | exact (proj2 AD1) | apply shadow_of_length; lia
      | exact AUX1 | rewrite Q2, u_small by lia; lia
      | rewrite Q2, u_small by lia; exact STKlo | lia | rewrite Q2, u_small by lia; unfold AFREE_STACK; lia
      | rewrite Q2, u_small by lia; rewrite <- Zminus_mod_idemp_l, SP16; reflexivity
      | rewrite Q4, u_small by lia; exact ERR | exact (xs_inv _ _ XS1) | exact (xs_ac _ _ XS1)
      | apply (ah_chain_nil H HH); rewrite Q8; lia
      | cbn [map]; destruct TRC as (_ & _ & _ & T4 & _); exact T4 |].
